//   AddressPosition, CService, CAddress, CExtKey/CExtPubKey, FeeFrac, CTxDestination
//   (+ all its alternatives), CPubKey, KeyOriginInfo, BlockTxPosition, std::pair, ...
// Include this header in your *_tests.cpp to print values on failure.
```

